import threading
import urllib.parse
import sqlalchemy
import sqlalchemy.orm
import sqlalchemy.engine.reflection
import sqlalchemy.schema
from IQCommon import pandas as pd
from sqlalchemy.sql import compiler
from IQData.plugins.plugin_system_db_tools.db_utils import DEFAULT_ENGINE_CONFIG, retry, DB_DEFAULT_DRIVER, CHUNK_SIZE_MERGE, CHUNK_SIZE
from IQCommon.exception import get_traceback_message
from IQCommon.logger import system_log
class DataBase(object):
    __doc__ = '\n    数据库对象\n    '
    _type = None
    def __init__(self, db_name, db_config, *args, **kwargs):
        self._local = threading.local()
        self.db_name = db_name
        self.db_config = db_config
        self._session_maker = self._get_session_maker()
    @classmethod
    def get_database(cls, db_name, db_type='sql', db_config=None, *args, **kwargs):
        if (cls._type == db_type):
            return cls(*args, db_name=db_name, db_config=db_config, **kwargs)
        else:
            for sub_cls in cls.__subclasses__():
                instance = sub_cls.get_database(db_name, db_type, db_config, *args, **kwargs)
                if (instance is not None):
                    return instance
    def get_session(self):
        try:
            session = self._local.session
        except AttributeError:
            system_log.error(get_traceback_message())
            session = self._session_maker()
            self._local.session = None
        return session
    def _get_session_maker(self, *args, **kwargs):
        raise NotImplementedError()
class SQLBase(DataBase):
    __doc__ = '\n    关系型数据库对象\n    '
    def __init__(self, db_name, db_config=None, enable_join=True, schema=None, result_rows_limit=100000):
        super(SQLBase, self).__init__(db_name, db_config)
        self._enable_join = enable_join
        self._schema = schema
        self._result_rows_limit = result_rows_limit
    def _get_session_maker(self):
        engine_argument = self.db_config.copy()
        name_or_url = engine_argument.pop('name_or_url', None)
        if (name_or_url is None):
            dialect = engine_argument.pop('dialect', 'mysql')
            driver = (engine_argument.pop('driver', None) or DB_DEFAULT_DRIVER.get(dialect))
            if (not driver):
                agreement = dialect
            agreement = '{}+{}'.format(dialect, driver)
            user_name = engine_argument.pop('user', None)
            if (user_name is not None):
                user_name = urllib.parse.quote_plus(user_name)
                passwd = engine_argument.pop('passwd', None)
                if (passwd is None):
                    user_name_password = user_name
                else:
                    passwd = urllib.parse.quote_plus(passwd)
                    user_name_password = '{}:{}'.format(user_name, passwd)
                user_name_password += '@'
            else:
                user_name_password = ''
            host = engine_argument.pop('host', '127.0.0.1')
            port = engine_argument.pop('port', 3306)
            db = engine_argument.pop('db', 'iqe_data')
            db = urllib.parse.quote_plus(db)
            charset = engine_argument.pop('charset', None)
            if (charset is None):
                charset = ''
            else:
                charset = '?charset={}'.format(charset)
            name_or_url = '{}://{}{}:{}/{}{}'.format(agreement, user_name_password, host, port, db, charset)
        engine_argument = dict(DEFAULT_ENGINE_CONFIG, **engine_argument)
        engine = sqlalchemy.create_engine(name_or_url, **engine_argument)
        return sqlalchemy.orm.sessionmaker(bind=engine)
    @property
    def engine(self):
        return self._session_maker.kw['bind']
    return (__classcell__ := __class__)
class BaseTools(object):
    __doc__ = '\n    基础工具集\n    '
    _schema_map = None
class SQLTools(BaseTools):
    __doc__ = '\n    关系型数据库工具集\n    '
    _schema = None
    _schema_map = None
    _table_names = None
    _view_names = None
    _table_base = None
    def _load_table_names(self):
        inspector = sqlalchemy.engine.reflection.Inspector.from_engine(self.engine)
        table_names = inspector.get_table_names()
        return set(map(str, table_names))
    def _load_view_names(self):
        inspector = sqlalchemy.engine.reflection.Inspector.from_engine(self.engine)
        view_names = inspector.get_view_names(schema=self._schema)
        return set(map(str, view_names))
    def _load_table_base(self, name):
        try:
            return self._table_base[name]
            return None
        except TypeError:
            system_log.error(get_traceback_message())
            self._table_base = {}
        except KeyError: system_log.error(get_traceback_message())
        table = sqlalchemy.schema.Table(name, sqlalchemy.schema.MetaData(), autoload=True, autoload_with=self.engine, schema=self._schema)
        self._table_base[name] = table
        return table
    def _load_table_class(self, table_name):
        table = self._load_table_base(table_name)
        table_class = type(table_name, (object,), {})
        exclude_columns = ['JSID']
        if (len(table.primary_key) != 0):
            sqlalchemy.orm.mapper(table_class, table, exclude_properties=exclude_columns)
        else:
            sqlalchemy.orm.mapper(table_class, table, primary_key=[getattr(table.c, table.c.keys()[0])], exclude_properties=exclude_columns)
        return table_class
    def _load_view_class(self, view_name):
        table = self._load_table_base(view_name)
        view_class = type(view_name, (object,), {})
        sqlalchemy.orm.mapper(view_class, table, primary_key=[getattr(table.c, table.c.keys()[0])])
        return view_class
    @property
    def table_names(self):
        if (self._table_names is None):
            self._table_names = self._load_table_names()
        return self._table_names
    @property
    def view_names(self):
        if (self._view_names is None):
            self._view_names = self._load_view_names()
        return self._view_names
    def __getattr__(self, item):
        return self.get_table(item)
    @retry
    def get_table(self, table_name):
        try:
            return self._schema_map[table_name]
            return None
        except TypeError:
            system_log.error(get_traceback_message())
            self._schema_map = {}
        except KeyError: system_log.error(get_traceback_message())
        if (table_name in self.table_names):
            self._schema_map[table_name] = self._load_table_class(table_name)
            return self._schema_map[table_name]
        elif (table_name in self.view_names):
            self._schema_map[table_name] = self._load_view_class(table_name)
            return self._schema_map[table_name]
        else:
            self._table_names = None
            if (table_name in self.table_names):
                self._schema_map[table_name] = self._load_table_class(table_name)
                return self._schema_map[table_name]
            else:
                self._view_names = None
                if (table_name in self.view_names):
                    self._schema_map[table_name] = self._load_view_class(table_name)
                    return self._schema_map[table_name]
                else:
                    raise AttributeError(f'{self.__class__.__name__!r} object has no attribute {table_name!r}')
    @retry
    def run_query(self, query_obj):
        if (not self._enable_join):
            pass
        limit = self._result_rows_limit
        if query_obj._limit:
            limit = min(query_obj._limit, limit)
        query_obj = query_obj.limit(limit)
        statement = query_obj.statement
        comp = compiler.SQLCompiler(self.engine.dialect, statement)
        return pd.read_sql(comp.string, con=self.engine, params=comp.params)
    @retry
    def insert(self, table_name, data):
        try:
            if isinstance(data, pd.DataFrame):
                data.to_sql(table_name, con=self.engine, if_exists='append', index=False, index_label=None, chunksize=CHUNK_SIZE)
                self.engine.dispose()
        except Exception as e:
            system_log.error(get_traceback_message())
            raise e
    @retry
    def merge(self, table_name, data, flush=True, commit=True):
        data_convert = data.to_dict('records')
        cycle = ((len(data_convert) - 1) // CHUNK_SIZE_MERGE + 1)
        session = self.get_session()
        columns = list(data.columns)
        for i in range(cycle):
            value_template = ', '.join(['{column} = values({column})'.format(column) for column in columns])
            sql_template = 'INSERT INTO {table_name} ({column_names}) VALUES ({value_space}) on duplicate key update {value_template}'.format(table_name=table_name, column_names=', '.join(columns), value_template=value_template, value_space=', '.join([':' + column for column in columns]))
            session.execute(sql_template, data_convert[i * CHUNK_SIZE_MERGE:(i + 1) * CHUNK_SIZE_MERGE])
            if commit:
                session.commit()
                continue
            elif flush:
                session.flush()
    def execute_sql(self, sql, params=None):
        session = self.get_session()
        c = session.execute(sql, params)
        session.commit()
        if (c.cursor is not None):
            columns = [d[0] for d in c.cursor.description]
            return pd.DataFrame(list(c.fetchall()), columns=columns)
        else:
            return pd.DataFrame()
    def query(self, *args, **kwargs):
        return self.get_session().query(*args, **kwargs)
    def commit(self):
        self.get_session().commit()
    def flush(self):
        self.get_session().flush()
    def rollback(self):
        self.get_session().rollback()
    @retry
    def to_database(self, table_name, data, if_exists='replace', index=False, index_label=None, dtype=None):
        try:
            if isinstance(data, pd.DataFrame):
                data.to_sql(table_name, con=self.engine, if_exists=if_exists, index=index, index_label=index_label, chunksize=CHUNK_SIZE, dtype=dtype)
                self.engine.dispose()
                return None
            else:
                raise RuntimeError('运行异常:，to_database接口只支持pandas.DataFrame类型的对象')
        except Exception as e:
            system_log.error(get_traceback_message())
            raise e
class SQLDataBase(SQLBase, SQLTools):
    __doc__ = '\n    关系型数据库功能对象\n    '
    _type = 'sql'
